  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import java.math.BigDecimal;
  5	import java.math.RoundingMode;
  6	import java.time.LocalDate;
  7	import java.time.Month;
  8	import java.util.Map;
  9	
 10	/**
 11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 13	 * (half-even) at every step.
 14	 */
 15	public final class PriceCalculator {
 16	
 17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 18	    static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 19	
 20	    private final Map<RatePlan, RatePlanStrategy> strategies;
 21	
 22	    public PriceCalculator() {
 23	        this.strategies = Map.of(
 24	                RatePlan.STANDARD, new StandardRatePlanStrategy(this),
 25	                RatePlan.NON_REFUNDABLE, new NonRefundableRatePlanStrategy(this),
 26	                RatePlan.CORPORATE, new CorporateRatePlanStrategy(this),
 27	                RatePlan.WEEKEND_PACKAGE, new WeekendPackageRatePlanStrategy(),
 28	                RatePlan.LONG_STAY, new LongStayRatePlanStrategy(this));
 29	    }
 30	
 31	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 32	        RatePlanStrategy strategy = strategies.get(ratePlan);
 33	        if (ratePlan == RatePlan.CORPORATE) {
 34	            return ((CorporateRatePlanStrategy) strategy).calculatePrice(room, checkIn, checkOut, companyCode);
 35	        }
 36	        return strategy.calculatePrice(room, checkIn, checkOut);
 37	    }
 38	
 39	    RatePlanStrategy strategyFor(RatePlan ratePlan) {
 40	        return strategies.get(ratePlan);
 41	    }
 42	
 43	    /** Calculates price based on nightly rates with optional discount. */
 44	    Price calculateByNightlyRate(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
 45	        int nights = 0;
 46	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 47	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 48	            subtotal = subtotal.add(nightPrice(room, night));
 49	            nights++;
 50	        }
 51	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 52	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 53	    }
 54	
 55	    BigDecimal nightPrice(Room room, LocalDate night) {
 56	        BigDecimal nightlyRate = room.nightlyRate();
 57	        if (isHighSeason(night)) {
 58	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 59	        }
 60	        return cents(nightlyRate);
 61	    }
 62	
 63	    /** High season: from December 15 to the end of February, and the whole of July. */
 64	    static boolean isHighSeason(LocalDate date) {
 65	        Month month = date.getMonth();
 66	        return month == Month.JANUARY
 67	                || month == Month.FEBRUARY
 68	                || month == Month.JULY
 69	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 70	    }
 71	
 72	    static BigDecimal cents(BigDecimal value) {
 73	        return value.setScale(2, ROUNDING_MODE);
 74	    }
 75	}
