 77	
 78	import hotel.rooms.Room;
 79	import java.math.BigDecimal;
 80	import java.time.LocalDate;
 81	import java.util.Map;
 82	
 83	/** Corporate agreement: a discount based on the company code. Full refund on cancellation. */
 84	final class CorporateRatePlanStrategy implements RatePlanStrategy {
 85	
 86	    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
 87	            "TECNOSUL", new BigDecimal("0.12"),
 88	            "AGROVALE", new BigDecimal("0.18"),
 89	            "FARMAVIDA", new BigDecimal("0.25"));
 90	
 91	    private final PriceCalculator priceCalculator;
 92	
 93	    CorporateRatePlanStrategy(PriceCalculator priceCalculator) {
 94	        this.priceCalculator = priceCalculator;
 95	    }
 96	
 97	    @Override
 98	    public void validate(NewReservation request, Room room) {
 99	        String companyCode = request.companyCode();
100	        if (companyCode == null || companyCode.isEmpty()) {
101	            throw new HotelException(ErrorCode.INVALID_REQUEST, "company code is required for corporate rate plan");
102	        }
103	        if (!COMPANY_DISCOUNTS.containsKey(companyCode)) {
104	            throw new HotelException(ErrorCode.INVALID_REQUEST, "unknown company code: " + companyCode);
105	        }
106	    }
107	
108	    @Override
109	    public Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut) {
110	        throw new UnsupportedOperationException("calculatePrice requires company code");
111	    }
112	
113	    Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
114	        BigDecimal discountRate = COMPANY_DISCOUNTS.get(companyCode);
115	        return priceCalculator.calculateByNightlyRate(room, checkIn, checkOut, discountRate);
116	    }
117	
118	    @Override
119	    public BigDecimal refundAmount(BigDecimal amountPaid) {
120	        return amountPaid;
121	    }
122	}
